// @ts-nocheck
// ===== Extruder03 : อ่านน้ำหนักจาก PLC Omron NJ 192.168.250.1 ด้วย FINS UDP (ทดสอบแล้วว่า SA1=2 ใช้ได้) =====
// ค่าที่เจอ D554=12336 (0x3030 = "00"), D555=11824 (0x2E30 = ".0") → PLC เก็บน้ำหนักเป็น "ตัวอักษร ASCII" จากเครื่องชั่ง
// จึงอ่านช่วง D540–D579 มาทั้งก้อน แล้วถอดเป็นข้อความ หาเลขน้ำหนักในนั้น
// NJ เก็บ STRING แบบ byte ต่ำก่อน -> ต้องสลับ byte ในแต่ละ word ("TS+," -> "ST,+")
// รูปแบบเครื่องชั่ง: "ST,+0000.000 g"  ST=นิ่ง US=ยังไม่นิ่ง OL=เกินพิกัด
const HOST = "192.168.250.1", DA1 = 1, SA1 = 50;   // SA1 = เลขท้าย IP กล่อง (eth0 192.168.250.50)
const START = 550, COUNT = 8;           // อ่านแค่ D550–D557 ("ST,+0000.000 g") ให้ PLC ทำงานน้อยที่สุด
const W_FROM = 550, W_TO = 557;         // ช่วงที่ใช้หาเลขน้ำหนัก (word)
const SWAP = true;                      // สลับ byte (NJ = true)
const RETRY = 0;                        // ลองซ้ำเมื่อ timeout (สายมี packet หาย)
const ERR_AFTER = 20;                   // timeout ติดกันกี่ครั้งถึงแจ้ง error

function wordStr(w) { let a = (w >> 8) & 0xFF, b = w & 0xFF; if (SWAP) { const t = a; a = b; b = t; } return [a, b].map(c => c >= 32 && c < 127 ? String.fromCharCode(c) : "·").join(""); }

// ---- ใช้ socket เดียวค้างไว้ (ไม่เปิด-ปิดทุกรอบ) -> PLC/HMI ไม่ต้องรับภาระเพิ่ม ----
let S = context.get("S");
if (!S) {
    const sock = dgram.createSocket("udp4");
    S = { sock, pending: null };
    sock.on("error", e => { if (S.pending) S.pending("socket " + e.code); });
    sock.on("message", r => { if (S.pending && r.length >= 14 && r[9] === S.sid) S.pending(null, r); });
    sock.bind(0);
    context.set("S", S);
}
if (S.pending) return null;                       // รอบก่อนยังไม่ตอบ -> ข้ามรอบนี้ (ไม่ยิงซ้อน)
const sid = ((S.sid || 0) + 1) & 0xFF; S.sid = sid;
// ทุก 4 รอบ (≈2 วินาที) อ่าน PRODUCTION NAME ที่ D210 (พนักงานพิมพ์เลขรุ่น 1–8 บนจอ HMI)
const cyc = ((context.get("cyc") || 0) + 1) % 4; context.set("cyc", cyc);
const NAME_D = 210, NAME_W = 5;
const isName = cyc === 0;
const RS = isName ? NAME_D : START, RC = isName ? NAME_W : COUNT;
const req = Buffer.from([0x80, 0, 0x02, 0, DA1, 0, 0, SA1, 0, sid,
    0x01, 0x01, 0x82, (RS >> 8) & 0xFF, RS & 0xFF, 0, (RC >> 8) & 0xFF, RC & 0xFF]);
const timer = setTimeout(() => S.pending && S.pending("timeout"), 400);
S.pending = (err, r) => {
    clearTimeout(timer); S.pending = null;
    if (err) {
        const n = (context.get("fail") || 0) + 1; context.set("fail", n);
        if (n >= ERR_AFTER) node.status({ fill: "red", shape: "ring", text: err + " ติดกัน " + n + " ครั้ง" });
        if (n === ERR_AFTER || (n > ERR_AFTER && n % 120 === 0)) node.send([null, null, { payload: { error: err + " ติดกัน " + n + " ครั้ง (เช็คสาย LAN / PLC)" } }]);
        return;
    }
    context.set("fail", 0);
    const ec = r.readUInt16BE(12);
    if (ec !== 0 && ec !== 0x0040) { node.status({ fill: "red", shape: "dot", text: "end code 0x" + ec.toString(16) }); node.send([null, null, { payload: { error: "PLC end code 0x" + ec.toString(16) } }]); return; }
    if (isName) {
        let nm = ""; for (let k = 0; k < NAME_W; k++) nm += wordStr(r.readUInt16BE(14 + k * 2));
        nm = nm.replace(/·/g, " ").trim();
        const words = []; for (let k = 0; k < NAME_W; k++) words.push(r.readUInt16BE(14 + k * 2));
        flow.set("ex03_model_words", words);          // เก็บค่าดิบไว้ด้วย (กรณี HMI เก็บเป็นตัวเลข ไม่ใช่ข้อความ)
        const key = nm + "|" + words.join(",");
        if (context.get("nameKey") !== key) {
            context.set("nameKey", key);
            flow.set("ex03_model_raw", nm);
            node.send([null, { payload: { "PRODUCTION NAME (D210)": nm, words: words.map((v, i) => "D" + (NAME_D + i) + "=" + v + " (0x" + v.toString(16).padStart(4, "0") + ")") } }, null]);
        }
        return;
    }
    const w = []; for (let k = 0; k < COUNT; k++) w.push(r.readUInt16BE(14 + k * 2));
    const at = d => w[d - START];
    // ข้อความ ASCII ของช่วงน้ำหนัก
    let txt = ""; for (let d = W_FROM; d <= W_TO; d++) txt += wordStr(at(d));
    txt = txt.replace(/·/g, " ").replace(/\s+/g, " ").trim();
    // "ST,+0000.000 g" -> สถานะ, เครื่องหมาย, ตัวเลข, หน่วย (เอาชุดแรก)
    const mm = txt.match(/([A-Z]{2})?\s*,?\s*([+-])?\s*(\d+(?:\.\d+)?)\s*([a-z]{1,3})?/);
    const weight = mm ? parseFloat((mm[2] === "-" ? "-" : "") + mm[3]) : null;
    const UNIT = (mm && mm[4]) || "";
    const stat = mm && mm[1] ? ({ ST: "นิ่ง", US: "ยังไม่นิ่ง", OL: "เกินพิกัด", QT: "นับชิ้น" }[mm[1]] || mm[1]) : "";
    flow.set("ex03_weight", { weight, unit: UNIT, stable: mm && mm[1] === "ST", text: txt, ts: Date.now() });
    node.status({ fill: weight === null ? "yellow" : mm[1] === "ST" ? "green" : "yellow", shape: "dot", text: (weight === null ? "ไม่พบตัวเลข" : weight + " " + UNIT + (stat ? " · " + stat : "")) });
    const dump = {};
    for (let d = START; d < START + COUNT; d++) { const v = at(d); dump["D" + d] = v + " | 0x" + v.toString(16).padStart(4, "0") + " | \"" + wordStr(v) + "\""; }
    let all = ""; for (let d = START; d < START + COUNT; d++) all += wordStr(at(d));
    node.send([
        { payload: { machine: "Extruder03", weight, unit: UNIT, stable: !!(mm && mm[1] === "ST"), สถานะ: stat, ข้อความจากเครื่องชั่ง: txt, time: new Date().toLocaleTimeString("th-TH") } },
        null,
        null
    ]);
};
S.sock.send(req, 9600, HOST, e => { if (e && S.pending) S.pending("send " + e.code); });
return null;

// @ts-nocheck
// ===== ส่งน้ำหนักขึ้น Server เฉพาะ "ชั่งเสร็จ 1 ครั้ง" =====
// - น้ำหนัก ไม่เกิน 1.0 g : ไม่ส่ง (รอวางของ / ค่าแกว่ง)
// - วางของแล้ว + นิ่ง (ST) + ค่าเดิมติดกัน NEED_SAME รอบ -> ส่ง 1 ครั้ง
// - ยังวางค้างอยู่ -> ไม่ส่งซ้ำ จนกว่าจะยกออก (กลับเป็น 0) แล้ววางชิ้นใหม่
// - ส่งไม่สำเร็จ -> เก็บคิวไว้ ส่งใหม่รอบถัดไป (ไม่หาย)
const MACHINE     = "Extruder03";
const MIN_G       = 1.0;   // ส่งเมื่อน้ำหนัก > 1.0 g เท่านั้น (หน่วย kg จะแปลงเป็นกรัมก่อนเทียบ)
const NEED_SAME   = 2;     // ค่าเดิมติดกันกี่รอบถึงนับว่านิ่ง (รอบละ 0.5 วินาที ≈ 1 วินาที)
const RESEND_DIFF = 0;     // วางค้างแต่น้ำหนักเปลี่ยนเกินค่านี้ -> ส่งใหม่ (0 = ไม่ส่ง)

// ส่งของที่ค้างในคิวก่อน (ครั้งละ 1)
const q = flow.get("ex03_queue") || [];
if (q.length) { const item = q.shift(); flow.set("ex03_queue", q); node.send({ payload: item, queued: true }); }

const p = msg.payload || {}, w = p.weight;
if (w === null || w === undefined || isNaN(w)) return null;

const grams = String(p.unit || "").toLowerCase() === "kg" ? w * 1000 : w;
if (grams <= MIN_G) {
    context.set("armed", true); context.set("same", 0); context.set("last", null);
    node.status({ fill: "grey", shape: "ring", text: "รอวางของ · ส่งแล้ว " + (context.get("count") || 0) + " ครั้ง" + (q.length ? " · ค้างคิว " + q.length : "") });
    return null;
}
const same = context.get("last") === w ? (context.get("same") || 0) + 1 : 1;
context.set("same", same); context.set("last", w);
if (!p.stable || same < NEED_SAME) { node.status({ fill: "yellow", shape: "ring", text: "รอนิ่ง " + w + " " + (p.unit || "") }); return null; }

const armed = context.get("armed") !== false, sentW = context.get("sentW");
if (armed || (RESEND_DIFF > 0 && sentW != null && Math.abs(w - sentW) >= RESEND_DIFF)) {
    context.set("armed", false); context.set("sentW", w);
    const n = (context.get("count") || 0) + 1; context.set("count", n);
    node.status({ fill: "green", shape: "dot", text: "ส่ง " + w + " " + (p.unit || "") + " · ครั้งที่ " + n });
    const md = flow.get("ex03_model");
    return { payload: { machine: MACHINE, weight: w, unit: p.unit || "", stable: true, model: md ? md.name : "", barcode: md ? (md.barcode || "") : "", min: md ? md.min : null, max: md ? md.max : null,
                        result: md && md.min != null ? (w >= md.min && w <= md.max ? "OK" : "NG") : "", text: (md ? (md.barcode ? md.barcode + " " : "") + md.name + " | " : "") + (p["ข้อความจากเครื่องชั่ง"] || "") } };
}
node.status({ fill: "blue", shape: "dot", text: "ส่งแล้ว " + sentW + " · รอยกของออก" });
return null;

// server ตอบไม่ใช่ 200 -> เข้าคิวเหมือน error
if (msg.statusCode !== 200) {
    const q = flow.get("ex03_queue") || [];
    const body = msg.sent || null;
    if (body && q.length < 500) { q.push(body); flow.set("ex03_queue", q); }
    node.status({ fill: "red", shape: "ring", text: "HTTP " + msg.statusCode + " · ค้างคิว " + q.length });
} else node.status({ fill: "green", shape: "dot", text: "บันทึกแล้ว " + new Date().toLocaleTimeString("th-TH") });
return msg;

// ส่งไม่สำเร็จ -> เก็บเข้าคิว (สูงสุด 500 รายการ) ให้ node ส่งค่าลองใหม่
const q = flow.get("ex03_queue") || [];
if (msg.sent && msg.sent.weight > 0 && q.length < 500) q.push(msg.sent);
flow.set("ex03_queue", q);
node.status({ fill: "red", shape: "ring", text: "ส่งไม่ได้ · ค้างคิว " + q.length });
return { payload: { error: msg.error && msg.error.message, ค้างคิว: q.length } };

// @ts-nocheck
// ===== คุมไฟ Tower: DO1 = เขียว, DO2 = แดง =====
// msg.payload: "green" | "red" | "off"  (หรือ true/false สำหรับทดสอบ)
// กันไฟติดพร้อมกัน: ปิดดวงหนึ่งก่อน แล้วค่อยเปิดอีกดวง
const c = String(msg.payload).toLowerCase();
const OFF = { payload: false }, ON = { payload: true };
if (c === "green") {
    node.send([null, OFF]);            // ปิดแดงก่อน
    node.send([ON, null]);             // เปิดเขียว
} else if (c === "red") {
    node.send([OFF, null]);            // ปิดเขียวก่อน
    node.send([null, ON]);             // เปิดแดง
} else {
    node.send([OFF, OFF]);             // ดับทั้งคู่
}
node.status({ fill: c === "green" ? "green" : c === "red" ? "red" : "grey", shape: "dot", text: c === "green" || c === "red" ? c.toUpperCase() : "OFF" });
return null;

// @ts-nocheck
// ===== ตัดสินผลชั่ง -> สีไฟ Tower =====
// รับ msg.payload = { weight, unit, stable } จาก flow Extruder03 (ผ่าน link) หรือจากปุ่มทดสอบ
// ส่งออกเฉพาะเมื่อสีเปลี่ยน: "green" | "red" | "off"
// ===== ตารางมาตรฐานน้ำหนัก (Weight Standard) — พนักงานยิงบาร์โค้ดรุ่นลงช่อง PRODUCTION NAME (D210) บนจอ HMI =====
//  อัปเดตตามใบ Weight Standard ล่าสุด (2026-10-19: SUPER SOFT 41.00-41.3) · 2026-10-22: SUPER SOFT 41.1-41.3 · 2026-10-23: ไม่ตรงรุ่น = ไฟดับ
//  2026-10-28 (Weight_Standard_Barcode.xlsx): S-Soft = SUPER SOFT2027 41.1-41.4 · เพิ่ม S-SO25 = SUPER SOFT2025 41.35-41.5
//  ตารางเดียวกันแสดงบนหน้าเว็บ WeightLog.aspx (การ์ด Weight Standard + พิมพ์บาร์โค้ด) -> แก้ค่าที่นี่ ต้องแก้ในหน้าเว็บด้วย
//  [บาร์โค้ด (ไม่เกิน 8 ตัวอักษร ตามช่องบน HMI), ชื่อรุ่น, Min g, Max g]      *** แก้ค่าในตารางนี้ได้เลย แล้ว Deploy ***
const SPECS = [
    ["S-Range",   "Super Range",  40.0, 40.3],
    ["C-Practi",  "CG Practice",  40.0, 40.3],
    ["P-Practi",  "Pro Practice", 36.0, 36.3],
    ["L-Fling",   "LTD Flight",   38.8, 39.2],
    ["S-Soft",    "SUPER SOFT2027", 41.1, 41.4],
    ["W-BIRD",    "WAR BIRD",     40.5, 40.5],   // ใบ Spec (อัปเดต) ยังเขียน 40.5-40.5 แต่ค่าตั้ง 40.3 -> ตรวจค่าที่ถูกต้องอีกครั้ง
    ["HE-DIABL",  "HEX DIABLO",   41.8, 42.2],   // บาร์โค้ดจริง HE-DIABLO (9 ตัว) ช่อง HMI รับ 8 ตัว -> HE-DIABL
    ["S-FAST",    "SUPER FAST",   41.1, 41.3],
    ["S-SO25",    "SUPER SOFT2025", 41.35, 41.5]
];
// เทียบบาร์โค้ดแบบไม่สนตัวพิมพ์เล็ก/ใหญ่ และช่องว่าง · ใช้ "ขึ้นต้นด้วย" (กันตัวอักษรเก่าค้างท้าย เช่น "S-SoftBLO")
// ยังพิมพ์เลข 1–9 แทนได้ (สำรอง) · ไม่ตรงรุ่นใดเลย / ยังไม่ยิงรุ่น = ไฟดับ (ไม่ตัดสิน)
const norm = t => String(t || "").toUpperCase().replace(/\s+/g, "");
const raw = String(flow.get("ex03_model_raw") || "").trim();
const key = norm(raw);
let code = null;
const byLen = SPECS.map((sp, i) => ({ i, k: norm(sp[0]) })).sort((a, b) => b.k.length - a.k.length);
for (const x of byLen) if (key === x.k || key.startsWith(x.k)) { code = x.i + 1; break; }
if (!code) { const mNum = key.match(/^(\d+)$/); if (mNum && SPECS[+mNum[1] - 1]) code = +mNum[1]; }
const DEFAULT = ["Not ScanBarcode", 0, 0];   // ไม่ตรงรุ่นใด -> ไม่ใช้ช่วงน้ำหนัก ไฟห้ามติด
const spec = code ? SPECS[code - 1].slice(1) : DEFAULT;
if (flow.get("ex03_model_code") !== code) { flow.set("ex03_model_code", code); flow.set("ex03_model", { code: code || 0, barcode: code ? SPECS[code - 1][0] : "", name: spec[0], min: code ? spec[1] : null, max: code ? spec[2] : null }); }   // Not ScanBarcode -> ไม่มี Spec / ไม่ตัดสิน OK-NG
const MIN_G = spec[1], MAX_G = spec[2];
const EMPTY_G = 1.0;     // ไม่เกินค่านี้ = ไม่มีของบนเครื่องชั่ง -> ดับไฟ
const HOLD_MS = 1500;    // ยกของออกแล้ว ค้างสีไว้อีก 1.5 วินาที ให้พนักงานเห็นผลทัน
const FAST = true;       // true = ตัดสินทันทีที่ค่าคงที่ 2 รอบ ไม่ต้องรอเครื่องชั่งขึ้น ST

const p = msg.payload || {};
if (p.weight === null || p.weight === undefined || isNaN(p.weight)) return null;
const g = String(p.unit || "g").toLowerCase() === "kg" ? p.weight * 1000 : p.weight;

let color;
const prevW = context.get("prevW"); context.set("prevW", g);
const steady = prevW !== undefined && Math.abs(prevW - g) < 0.05;   // ค่าไม่เปลี่ยนจากรอบก่อน
if (!code) {                                      // ไม่ตรงรุ่นใด -> ดับไฟทันที ไม่ตัดสิน
    const t0 = context.get("offTimer"); if (t0) { clearTimeout(t0); context.set("offTimer", null); }
    node.status({ fill: "grey", shape: "ring", text: "Not ScanBarcode [D210=\"" + raw + "\"] · OFF · " + g + " g" });
    if (context.get("last") === "off") return null;
    context.set("last", "off");
    return { payload: "off", weight: g, model: "Not ScanBarcode" };
}
if (g <= EMPTY_G) color = "off";
else if (!(p.stable || (FAST && steady))) return null;  // ยังแกว่ง -> คงสีเดิมไว้
else color = (g >= MIN_G && g <= MAX_G) ? "green" : "red";

// ยกของออก: ค้างสีไว้ HOLD_MS ก่อนดับ (ถ้าวางชิ้นใหม่ระหว่างนี้ ยกเลิกการดับ)
const t = context.get("offTimer");
if (color !== "off" && t) { clearTimeout(t); context.set("offTimer", null); }
if (color === "off" && context.get("last") && context.get("last") !== "off") {
    if (!t) context.set("offTimer", setTimeout(() => {
        context.set("offTimer", null); context.set("last", "off");
        node.status({ fill: "grey", shape: "dot", text: "OFF" });
        node.send({ payload: "off" });
    }, HOLD_MS));
    return null;
}

if (context.get("last") === color) return null;        // สีเดิม ไม่ต้องสั่งซ้ำ
context.set("last", color);
node.status({ fill: color === "off" ? "grey" : color, shape: "dot",
              text: ((code ? SPECS[code - 1][0] + " · " : "[D210=\"" + raw + "\"] ") + spec[0] + " · ") + color.toUpperCase() + (color === "off" ? "" : "  " + g + " g  (" + MIN_G + "–" + MAX_G + ")") });
return { payload: color, weight: g, model: spec[0] };

// @ts-nocheck
// ===== ส่ง "ค่าสด" ให้หน้า WeightLog.aspx แสดงตัวเลขวิ่งตามตราชั่ง (ไม่บันทึกลง DB) =====
// - ส่งเฉพาะตอนค่าเปลี่ยน และมีของบนตราชั่ง (> 1.0 g) · ยกออกแล้วส่ง 0 ครั้งเดียว
// - ตราชั่งว่าง: ส่ง heartbeat ทุก 5 วิ ให้หน้าเว็บรู้ว่าตราชั่งยังออนไลน์
// - รอบก่อนยังส่งไม่เสร็จ -> ข้าม (ไม่ให้คำขอค้างซ้อนกัน)
const MACHINE = "Extruder03", MIN_G = 1.0, HEARTBEAT_MS = 5000, BUSY_MS = 3000;
const p = msg.payload || {};
if (p.weight === null || p.weight === undefined || isNaN(p.weight)) return null;
const now = Date.now();
const busy = flow.get("ex03_live_busy") || 0;
if (busy && now - busy < BUSY_MS) return null;
const g = String(p.unit || "g").toLowerCase() === "kg" ? p.weight * 1000 : p.weight;
const loaded = g > MIN_G;
const prev = context.get("prevW");
context.set("prevW", p.weight);
const settled = loaded && (p.stable || prev === p.weight);   // นิ่ง = เครื่องชั่งขึ้น ST หรือค่าเท่ารอบก่อน (เหมือนตอนตัดสินไฟ)
const key = (loaded ? p.weight : 0) + "|" + settled;
const last = context.get("last") || {};
const changed = key !== last.key;
if (!changed && (loaded || now - (last.t || 0) < HEARTBEAT_MS)) return null;
context.set("last", { key, t: now });
flow.set("ex03_live_busy", now);
const md = flow.get("ex03_model");
const res = settled && md && md.min != null ? (p.weight >= md.min && p.weight <= md.max ? "OK" : "NG") : "";
node.status({ fill: settled ? (res === "NG" ? "red" : "green") : loaded ? "yellow" : "grey", shape: "dot",
              text: loaded ? p.weight + " " + (p.unit || "") + (settled ? " · นิ่ง " + res : " · กำลังชั่ง") : "ว่าง (heartbeat)" });
return { payload: { live: true, machine: MACHINE, weight: loaded ? p.weight : 0, unit: p.unit || "g", stable: settled,
                    model: md ? md.name : "", barcode: md ? (md.barcode || "") : "", code: 0, min: md ? md.min : null, max: md ? md.max : null, result: res } };

// ส่งค่าสดเสร็จ (สำเร็จหรือ error) -> ปลดล็อกให้ส่งรอบถัดไปได้
flow.set("ex03_live_busy", 0);
const ok = msg.statusCode === 200;
node.status(ok ? { fill: "green", shape: "dot", text: "OK " + new Date().toLocaleTimeString("th-TH") }
               : { fill: "red", shape: "ring", text: msg.error ? "ส่งไม่ได้: " + (msg.error.message || msg.error) : "HTTP " + msg.statusCode });
return null;
